WITH v AS (SELECT v.id FROM cartillas.versiones v JOIN cartillas.plantillas p ON p.id=v.plantilla_id WHERE p.codigo='TAPAS_DE_PUNTA_DE_EJE' AND v.numero=1),d(t,o) AS (VALUES('TAPAS DE PUNTA DE EJE',1),('LISTA DE INSTRUMENTOS :',2),('OBSERVACIONES:',3),('REALIZADO POR:',4)) INSERT INTO cartillas.secciones(version_id,titulo,orden) SELECT v.id,d.t,d.o FROM v CROSS JOIN d ON CONFLICT(version_id,orden) DO UPDATE SET titulo=EXCLUDED.titulo,activo=TRUE,actualizado_en=CURRENT_TIMESTAMP;
WITH v AS (SELECT v.id FROM cartillas.versiones v JOIN cartillas.plantillas p ON p.id=v.plantilla_id WHERE p.codigo='TAPAS_DE_PUNTA_DE_EJE' AND v.numero=1),s AS (SELECT id,titulo FROM cartillas.secciones WHERE version_id=(SELECT id FROM v)),f AS (SELECT jsonb_agg(jsonb_build_object('coche',c,'bogie',b,'eje',n) ORDER BY n) x FROM unnest(ARRAY['MA1','MA1','MA1','MA1','MB1','MB1','MB1','MB1','MB3','MB3','MB3','MB3','R','R','R','R','MB2','MB2','MB2','MB2','MA2','MA2','MA2','MA2']) WITH ORDINALITY a(c,n) JOIN unnest(ARRAY['PB3','PB3','PB4','PB4','PB6','PB6','PB2','PB2','PB6','PB6','PB2','PB2','TB1','TB1','TB2','TB2','PB2','PB2','PB6','PB6','PB4','PB4','PB3','PB3']) WITH ORDINALITY b(b,n) USING(n)),d(t,c,e,ty,o,cf) AS (VALUES('TAPAS DE PUNTA DE EJE','fecha','FECHA:','fecha',1,'{}'),('TAPAS DE PUNTA DE EJE','controles_tapas','TAPAS DE PUNTA DE EJE','tabla',2,jsonb_build_object('columnas',jsonb_build_array(jsonb_build_object('codigo','coche','etiqueta','Coche'),jsonb_build_object('codigo','bogie_izq','etiqueta','LADO IZQUIERDO BOGIE'),jsonb_build_object('codigo','bogie_der','etiqueta','LADO DERECHO BOGIE'),jsonb_build_object('codigo','eje','etiqueta','Eje'),jsonb_build_object('codigo','tapa_caja_100','etiqueta','TAPA CAJA GRASA / 100 Nm'),jsonb_build_object('codigo','tapa_plana_20','etiqueta','TAPA PLANA / 20 Nm'),jsonb_build_object('codigo','wsp_ts_20','etiqueta','WSP/TS / 20 Nm'),jsonb_build_object('codigo','retorno','etiqueta','RETORNO CORRIENTE'),jsonb_build_object('codigo','atp','etiqueta','ATP'),jsonb_build_object('codigo','seguro_rodamiento_180','etiqueta','SEGURO RODAMIENTO / 180 Nm'),jsonb_build_object('codigo','tacometro','etiqueta','TACOMETRO ATP'),jsonb_build_object('codigo','portaescobillas','etiqueta','FIJACION PORTAESCOBILLAS / 25 Nm'),jsonb_build_object('codigo','escobillas','etiqueta','FIJACION ESCOBILLAS / 10/16,5 Nm'),jsonb_build_object('codigo','placa_contacto','etiqueta','PLACA CONTACTO / 20 Nm'),jsonb_build_object('codigo','tapa_intermedia','etiqueta','TAPA INTERMEDIA / 16,5/20 Nm'),jsonb_build_object('codigo','tapa_tacometro','etiqueta','TAPA TACOMETRO / 3,7-5/33 Nm')),'filasIniciales',(SELECT x FROM f))),('LISTA DE INSTRUMENTOS :','instrumentos','LISTA DE INSTRUMENTOS :','tabla',1,'{"columnas":[{"codigo":"codigo","etiqueta":"Código"},{"codigo":"descripcion","etiqueta":"Descripción"},{"codigo":"modelo","etiqueta":"Modelo / Marca"},{"codigo":"calibracion","etiqueta":"Fecha de Calibración"},{"codigo":"vencimiento","etiqueta":"Fecha de Vencimiento de calibración"},{"codigo":"observacion","etiqueta":"Observación"}],"filasIniciales":[{},{},{},{},{},{}]}'),('OBSERVACIONES:','observaciones','OBSERVACIONES:','texto',1,'{"multilinea":true}'),('REALIZADO POR:','personal','REALIZADO POR:','tabla',1,'{"columnas":[{"codigo":"personal","etiqueta":"PERSONAL"},{"codigo":"firma_fecha","etiqueta":"Nombre, Firma y Fecha"}],"filasIniciales":[{"personal":"Técnico A:"},{"personal":"Técnico B:"},{"personal":"Técnico C:"},{"personal":"Técnico D:"},{"personal":"Técnico E:"},{"personal":"Técnico F:"},{"personal":"Técnico G:"},{"personal":"Técnico H:"},{"personal":"Técnico I:"},{"personal":"Técnico J:"},{"personal":"Técnico K:"},{"personal":"Técnico L:"},{"personal":"Técnico M:"},{"personal":"Técnico N:"},{"personal":"Responsable 01:"},{"personal":"Responsable 02:"},{"personal":"Responsable de mantenimiento Q:"},{"personal":"Responsable de mantenimiento R:"}]}')) INSERT INTO cartillas.campos(seccion_id,codigo,etiqueta,tipo,orden,configuracion) SELECT s.id,d.c,d.e,d.ty,d.o,d.cf FROM d JOIN s ON s.titulo=d.t ON CONFLICT(seccion_id,codigo) DO UPDATE SET configuracion=EXCLUDED.configuracion,activo=TRUE,actualizado_en=CURRENT_TIMESTAMP;
